  let aS=0,iS=0,cS=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2=Math.sqrt((sx2-sX)**2+(sy2-sY)**2);
    aS+=Math.sin(d*f-t*sp)*amp;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    cS+=Math.sin((d+d2)*f*0.5-t*sp*0.8+0.7)*amp*0.5;
  }
  const n=src.length,act=aS/n,inh=iS/n,cross=cS/n;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin(sx*0.08+sy*0.06-t*1.3)*Math.cos(sx*0.05-sy*0.07+t*0.9)*0.3;
  const bg=bg1+bg2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
