  const cell2=Math.tanh(Math.sin(sx2*0.12-t*0.3)*Math.cos(sy2*0.12+t*0.4)*2)*0.2;
  const detail=Math.sin(Math.sin(sx*0.1+t)*2+Math.cos(sy*0.12-t*0.7)*2+t*0.5)*0.15;
  const reaction=Math.tanh((act-inh*0.7+cross*0.3+bg*0.25+spiral*0.3+detail)*2.2);
  const blend=reaction*0.7+(cell1*0.6+cell2*0.4)*0.3;
  const v=blend*0.5+0.5;
  const pal=[[5,12,52],[10,45,95],[15,85,115],[18,125,130],[45,160,125],[120,185,90],[200,195,60],[220,160,55],[215,120,65],[185,75,60],[140,40,55],[85,18,48],[40,12,42],[5,12,52]];
